#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    int countCells(vector<vector<char>>& grid, string pattern) {
        int m = grid.size(), n = grid[0].size();
        int pLen = pattern.size();
        vector<vector<bool>> hMatch(m, vector<bool>(n, false));
        vector<vector<bool>> vMatch(m, vector<bool>(n, false));

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j <= n - pLen; ++j) {
                bool ok = true;
                for (int k = 0; k < pLen; ++k) {
                    if (grid[i][j + k] != pattern[k]) { ok = false; break; }
                }
                if (ok) {
                    for (int k = 0; k < pLen; ++k) hMatch[i][j + k] = true;
                }
            }
        }

        for (int j = 0; j < n; ++j) {
            for (int i = 0; i <= m - pLen; ++i) {
                bool ok = true;
                for (int k = 0; k < pLen; ++k) {
                    if (grid[i + k][j] != pattern[k]) { ok = false; break; }
                }
                if (ok) {
                    for (int k = 0; k < pLen; ++k) vMatch[i + k][j] = true;
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (hMatch[i][j] && vMatch[i][j]) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int countCells(char[][] grid, String pattern) {
        int m = grid.length, n = grid[0].length;
        int pLen = pattern.length();
        boolean[][] hMatch = new boolean[m][n];
        boolean[][] vMatch = new boolean[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j <= n - pLen; j++) {
                boolean ok = true;
                for (int k = 0; k < pLen; k++) {
                    if (grid[i][j + k] != pattern.charAt(k)) { ok = false; break; }
                }
                if (ok) {
                    for (int k = 0; k < pLen; k++) hMatch[i][j + k] = true;
                }
            }
        }

        for (int j = 0; j < n; j++) {
            for (int i = 0; i <= m - pLen; i++) {
                boolean ok = true;
                for (int k = 0; k < pLen; k++) {
                    if (grid[i + k][j] != pattern.charAt(k)) { ok = false; break; }
                }
                if (ok) {
                    for (int k = 0; k < pLen; k++) vMatch[i + k][j] = true;
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (hMatch[i][j] && vMatch[i][j]) ans++;
            }
        }
        return ans;
    }
}

var countCells = function(grid, pattern) {
    const m = grid.length, n = grid[0].length;
    const pLen = pattern.length;
    const hMatch = Array.from({ length: m }, () => new Array(n).fill(false));
    const vMatch = Array.from({ length: m }, () => new Array(n).fill(false));

    for (let i = 0; i < m; i++) {
        const rowStr = grid[i].join("");
        for (let j = 0; j <= n - pLen; j++) {
            if (rowStr.substring(j, j + pLen) === pattern) {
                for (let k = 0; k < pLen; k++) hMatch[i][j + k] = true;
            }
        }
    }

    for (let j = 0; j < n; j++) {
        let colStr = "";
        for (let i = 0; i < m; i++) colStr += grid[i][j];
        for (let i = 0; i <= m - pLen; i++) {
            if (colStr.substring(i, i + pLen) === pattern) {
                for (let k = 0; k < pLen; k++) vMatch[i + k][j] = true;
            }
        }
    }

    let ans = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (hMatch[i][j] && vMatch[i][j]) ans++;
        }
    }
    return ans;
};
